o_setting.s_code:
// A selenite cluster: many straight sticks with pointed tips,
// low at the rim and high in the middle. Units: mm.

const n_tau = PI * 2;
const n_height = 150;
const n_its_layer = 150;
// Many corners: each stick needs enough of them to look round.
const n_its_corner = 240;
const n_height_cone = 6;
// No dome: the middle stick ends in a point on its own.
const n_height_dome = 0;
const n_overhang_dome = 60;

// Another number gives another cluster.
const n_seed = 4;
// The sticks: one in the middle, a ring around it, a ring around
// that. For each ring: how many, how far from the axis, how thick
// (radius), from which to which height the tips reach, and how
// long the pointed part is.
const a_o_ring = [
    { n_count: 6, n_dist: 15, n_radius: 9.5, n_h_min: 100, n_h_max: 128, n_taper: 22 },
    { n_count: 11, n_dist: 28, n_radius: 9, n_h_min: 45, n_h_max: 92, n_taper: 20 },
];
const o_center = { n_radius: 11, n_taper: 26 };
// How deep the fine grooves along each stick are.
const n_groove = 0.5;

// A fixed random number from 0 to 1 for each n.
function f_n_rand(n) {
    return fract(sin(n * 127.1 + n_seed * 311.7) * 43758.5453);
}

// Build the sticks once. Each has a place (n_x, n_y), a radius, a
// height, and a point (n_x_tip, n_y_tip) where its tip ends. The
// tip lies inside the next taller stick, so no stick ends in the
// air: a single wall cannot print that.
const a_o_stick = [{
    n_x: 0, n_y: 0, n_x_tip: 0, n_y_tip: 0,
    n_radius: o_center.n_radius,
    // A bit above the top, so the last layer is a small ring.
    n_h: n_height + 2.5,
    n_taper: o_center.n_taper,
}];
let a_o_parent = [a_o_stick[0]];
let n_id = 1;
for (const o_ring of a_o_ring) {
    const a_o_new = [];
    const n_turn = f_n_rand(n_id + 50);
    for (let n_it = 0; n_it < o_ring.n_count; n_it++, n_id++) {
        const n_angle = (n_it + n_turn + (f_n_rand(n_id) - 0.5) * 0.3)
            / o_ring.n_count * n_tau;
        const n_dist = o_ring.n_dist + (f_n_rand(n_id + 100) - 0.5) * 4;
        const o_stick = {
            n_x: sin(n_angle) * n_dist,
            n_y: cos(n_angle) * n_dist,
            n_radius: o_ring.n_radius + (f_n_rand(n_id + 200) - 0.5) * 2,
            n_h: mix(o_ring.n_h_min, o_ring.n_h_max, f_n_rand(n_id + 300)),
            n_taper: o_ring.n_taper,
        };
        // The nearest stick of the ring inside is its parent.
        let o_parent = a_o_parent[0];
        for (const o of a_o_parent) {
            if (distance(vec2(o.n_x, o.n_y), vec2(o_stick.n_x, o_stick.n_y))
                < distance(vec2(o_parent.n_x, o_parent.n_y),
                    vec2(o_stick.n_x, o_stick.n_y))) {
                o_parent = o;
            }
        }
        // The tip ends 60 % of the way to the parent's middle, and
        // below where the parent starts to get thinner.
        o_stick.n_x_tip = mix(o_stick.n_x, o_parent.n_x, 0.6);
        o_stick.n_y_tip = mix(o_stick.n_y, o_parent.n_y, 0.6);
        o_stick.n_h = min(o_stick.n_h, o_parent.n_h - o_parent.n_taper - 2);
        a_o_new.push(o_stick);
        a_o_stick.push(o_stick);
    }
    a_o_parent = a_o_new;
}

function f_o_p(n_it_layer_nor, n_it_corner_nor) {
    const n_z = n_it_layer_nor * n_height;
    const n_angle = n_it_corner_nor * n_tau;
    const n_dx = sin(n_angle);
    const n_dy = cos(n_angle);

    // Look from the axis outward in this corner's direction, and
    // take the farthest point of any stick there.
    let n_r = 0.8;
    for (let n_it = 0; n_it < a_o_stick.length; n_it++) {
        const o = a_o_stick[n_it];
        // 1 on the straight part, down to 0 at the tip.
        const n_s = clamp((o.n_h - n_z) / o.n_taper, 0, 1);
        if (n_s <= 0) continue;
        // The stick's circle at this height. In the pointed part
        // it shrinks toward the tip's place.
        const n_cx = mix(o.n_x_tip, o.n_x, n_s);
        const n_cy = mix(o.n_y_tip, o.n_y, n_s);
        const n_rad = o.n_radius * n_s;
        // Where the line of sight leaves the circle.
        const n_b = n_dx * n_cx + n_dy * n_cy;
        const n_disc = n_b * n_b - (n_cx * n_cx + n_cy * n_cy - n_rad * n_rad);
        if (n_disc < 0) continue;
        let n_t = n_b + sqrt(n_disc);
        // Fine grooves along the stick, like selenite's fibres.
        n_t += noise.simplex2(n_angle * 12, n_it * 7.3) * n_groove * n_s;
        n_r = max(n_r, n_t);
    }

    return {
        n_x: n_dx * n_r,
        n_y: n_dy * n_r,
        n_z: o_thread.n_z + n_height_cone + n_z,
    };
}

return {
    n_its_layer, n_its_corner, f_o_p,
};
